import requests
import json
import schedule
import time

BASE_URL = 'https://api.data.gov/regulations/v3/'
API_KEY = 'DEMO_KEY'

def fetch_policy_documents(keyword, per_page=25):
    params = {'api_key': API_KEY, 'per_page': per_page, 'encoded': 1}
    response = requests.get(BASE_URL + 'documents.json', params=params)
    return response.json()

def save_results(data, filename='policy_data.json'):
    with open(filename, 'w') as f:
        json.dump(data, f, indent=2)

def run_extraction():
    data = fetch_policy_documents('climate policy')
    save_results(data)
    print('Extraction complete.')

schedule.every().day.at('06:00').do(run_extraction)
if __name__ == '__main__':
    run_extraction()
    while True:
        schedule.run_pending()
        time.sleep(60)

